104. impl Inner {
105.     ///
106.     /// # Description
107.     ///
108.     /// Allocates a frame.
109.     ///
110.     /// # Returns
111.     ///
112.     /// Upon success, the address of the allocated frame is returned. Upon failure, an error is
113.     /// returned instead.
114.     ///
115.     #[verus_spec(result =>
116.         requires
117.             old(self).inv(),
118.         ensures
119.             final(self).inv(),
120.             match result {
121.                 Ok(frame) => {
122.                     &&& frame.inv()
123.                     &&& old(self)@.free_frames.contains(frame@)
124.                     &&& final(self)@ == FrameAllocView {
125.                         allocated_frames: old(self)@.allocated_frames.insert(frame@),
126.                         free_frames: old(self)@.free_frames.remove(frame@),
127.                         refcounts: old(self)@.refcounts.insert(frame@, 1int),
128.                     }
129.                 },
130.                 Err(_) => {
131.                     &&& final(self)@ == old(self)@
132.                     &&& old(self)@.free_frames.is_empty()
133.                 }
134.             },
135.     )]
136.     fn alloc(&mut self) -> Result<FrameAddress, Error> {
137.         let frame_number: usize = match self.bitmap.alloc() {
138.             Ok(index) => index,
139.             Err(error) => {
140.                 error!("{error:?}");
141.                 return Err(error);
142.             },
143.         };
144.         // Newly allocated frames have a single owner.
145.         debug_assert_eq!(self.refcount[frame_number], 0);
146.         self.refcount[frame_number] = 1;
147.         let frame_number: FrameNumber = match FrameNumber::from_raw_value(frame_number) {
148.             Some(frame_number) => frame_number,
149.             None => {
150.                 let reason: &str = "frame number is out of bounds";
151.                 error!("{reason:?}");
152.                 return Err(Error::new(ErrorCode::OutOfMemory, reason));
153.             },
154.         };
155. 
156.         // Attempt to convert the frame number to a frame address.
157.         match FrameAddress::from_frame_number(frame_number) {
158.             Ok(frame_address) => Ok(frame_address),
159.             Err(error) => {
160.                 error!("{error:?}");
161.                 Err(error)
162.             },
163.         }
164.     }
