166.     ///
167.     /// # Description
168.     ///
169.     /// Allocates `count` physically contiguous frames.
170.     ///
171.     /// # Parameters
172.     ///
173.     /// - `count`: Number of contiguous frames to allocate.
174.     ///
175.     /// # Returns
176.     ///
177.     /// Upon success, the base `FrameAddress` of the contiguous range is returned. Upon failure,
178.     /// an error is returned instead.
179.     ///
180.     #[verus_spec(result =>
181.         requires
182.             old(self).inv(),
183.             count > 0,
184.         ensures
185.             final(self).inv(),
186.             match result {
187.                 Ok(base) => {
188.                     &&& base.inv()
189.                     &&& ({
190.                         let frames = Set::new(|addr: int|
191.                             exists|i: int| 0 <= i < count && addr == #[trigger] (base@ + i * spec_page_size())
192.                         );
193.                         &&& frames.subset_of(old(self)@.free_frames)
194.                         &&& final(self)@ == FrameAllocView {
195.                             allocated_frames: old(self)@.allocated_frames.union(frames),
196.                             free_frames: old(self)@.free_frames.difference(frames),
197.                             refcounts: old(self)@.refcounts.union_prefer_right(
198.                                 Map::new(|addr: int| frames.contains(addr), |addr: int| 1int)
199.                             ),
200.                         }
201.                     })
202.                 },
203.                 Err(_) => {
204.                     final(self)@ == old(self)@
205.                 }
206.             },
207.     )]
208.     fn alloc_contiguous(&mut self, count: usize) -> Result<FrameAddress, Error> {
209.         let frame_number: usize = match self.bitmap.alloc_range(count) {
210.             Ok(index) => index,
211.             Err(error) => {
212.                 error!("{error:?} (count={count})");
213.                 return Err(error);
214.             },
215.         };
216.         // Newly allocated frames have a single owner.
217.         for i in frame_number..frame_number + count {
218.             debug_assert_eq!(self.refcount[i], 0);
219.             self.refcount[i] = 1;
220.         }
221.         let frame_number: FrameNumber = match FrameNumber::from_raw_value(frame_number) {
222.             Some(frame_number) => frame_number,
223.             None => {
224.                 let reason: &str = "frame number is out of bounds";
225.                 error!("{reason:?}");
